import{_ as o,o as r,c as a,aj as t}from"./chunks/framework.C6uXqnaX.js";const m=JSON.parse('{"title":"Hydration Missing Node on Path","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"errors/NG0509.md","filePath":"errors/NG0509.md"}'),s={name:"errors/NG0509.md"};function n(i,e,d,h,l,u){return r(),a("div",null,e[0]||(e[0]=[t('<h1 id="hydration-missing-node-on-path" tabindex="-1">Hydration Missing Node on Path <a class="header-anchor" href="#hydration-missing-node-on-path" aria-label="Permalink to &quot;Hydration Missing Node on Path&quot;">​</a></h1><p>Production builds show this error when Angular can&#39;t find a node during hydration. Angular follows a path that it saved during server-side rendering, but a node on this path is missing. This means that the DOM in the browser is different from the HTML from the server.</p><p>Production builds don&#39;t include error messages, so you see only the code <code>NG0509</code>. Development builds show the same problem as <a href="/errors/NG0502">error NG0502</a>, and the message tells you the host node and the path.</p><h2 id="common-causes" tabindex="-1">Common causes <a class="header-anchor" href="#common-causes" aria-label="Permalink to &quot;Common causes&quot;">​</a></h2><p>The causes are the same as for <a href="/errors/NG0500">error NG0500</a>. Also check for changes from outside your application, for example from a CDN feature or a browser extension. Read <a href="/guide/hydration#cdns-and-browser-extensions">CDNs and browser extensions</a> in the hydration guide.</p><h2 id="debugging-the-error" tabindex="-1">Debugging the error <a class="header-anchor" href="#debugging-the-error" aria-label="Permalink to &quot;Debugging the error&quot;">​</a></h2><ul><li>If you can see the problem in a development build, use that build. The <code>NG0502</code> message tells you the host node and the path.</li><li>Compare the HTML from production with the HTML from your local server. If you see <code>__cf_email__</code> elements, or if comment nodes are missing, a CDN feature is probably the cause.</li><li>Open the page in a browser profile with no extensions. If the error goes away, an extension is changing the page.</li></ul>',7)]))}const p=o(s,[["render",n]]);export{m as __pageData,p as default};
